import{_ as s,l as o,o as e,c as n,v as r,p as l,x as t,d as h,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Shamir 秘密共享","description":"","frontmatter":{"title":"Shamir 秘密共享","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shamir-secret-sharing.md","filePath":"cs/shamir-secret-sharing.md","lastUpdated":1789023840000}'),c={name:"cs/shamir-secret-sharing.md"};function p(_,a,B,E,S,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="shamir-秘密共享" tabindex="-1">Shamir 秘密共享 <a class="header-anchor" href="#shamir-秘密共享" aria-label="Permalink to &quot;Shamir 秘密共享&quot;">​</a></h1><div class="epigraph"><p>把秘密当成多项式在 0 处的值，发给每人一个点；$t$ 个点能插值，$t-1$ 个点在信息论上什么都不知道。阈值由多项式次数决定。</p><footer>—— Shamir, How to Share a Secret, Communications of the ACM, 1979</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/commitment-merkle-tree">承诺与 Merkle</a>把一个值绑进公开根。缺口是<strong>不公开、但要多人共管</strong>：任何少于阈值的集合不应得到秘密。HSM 备份常走这条，而不是把根钥复印 n 份。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把密钥切成 n 段明文，任何一段都可能泄漏部分比特。Shamir：在有限域上随机 \\(t-1\\) 次多项式，\\(f(0)=s\\)，份额是 \\((i,f(i))\\)。完善保密：少于 \\(t\\) 个点时 \\(s\\) 仍均匀。缺口是阈值方案，不是再讲 HKDF。</p><h3 id="份额也是密钥材料" tabindex="-1">份额也是密钥材料 <a class="header-anchor" href="#份额也是密钥材料" aria-label="Permalink to &quot;份额也是密钥材料&quot;">​</a></h3><p>存份额的主机被全拿仍达阈值。分发信道要保密且认证，否则份额被换（主动敌手）。</p><p><span class="marginnote">Shamir 1979。Feldman/Pedersen 可验证共享防经销商作恶，本课点名，细节留给 MPC。不要与「把文件 zip 分卷」混淆。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用次数 1 的直线在黑板上点名「两点定线、一点不定」。推广到 \\(t\\)。指出重构是拉格朗日插值，实现要在域上算，并防份额编号重复。</p>',12)),(e(),l(m,null,{default:t(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%A7%98%E5%AF%86%20s%3Df(0)%22%5D%20--%3E%20POLY%5B%22%E9%9A%8F%E6%9C%BA%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20POLY%20--%3E%20SH%5B%22n%20%E4%BB%BD%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20SH%20--%3E%20T%5B%22%E4%BB%BB%E6%84%8F%20t%20%E4%BB%BD%E5%8F%AF%E9%87%8D%E6%9E%84%22%5D%0A%20%20SH%20--%3E%20LT%5B%22%E5%B0%91%E4%BA%8E%20t%20%E4%BB%BD%E6%97%A0%E4%BF%A1%E6%81%AF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息论安全的拆分服务托管与灾难恢复。它不提供计算：份额持有人如何<strong>一起签名还不重构明文私钥</strong>，是下一课门限与 MPC。重构后的 \\(s\\) 又回到单点，策略上应在 HSM 内完成重构。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写主动攻击下的份额注入步骤。下一课门限签名与 MPC 直觉：计算发生在秘密共享之上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>承诺藏一个值；共享把值拆给多人。</li><li>Shamir：\\(t\\) 点重构，\\(t-1\\) 无信息。</li><li>份额信道要保密认证；重构点仍是 TCB。</li><li>下一课：门限签名与 MPC。</li><li>出处：Shamir, 1979；对照 Stinson 的密码学教材章节。</li></ul>',8))])}const P=s(c,[["render",p]]);export{A as __pageData,P as default};
